import 'package:flutter/material.dart'  import 'package:flutter_riverpod/flutter_riverpod.dart'  import 'package:go_router/go_router.dart'  import 'package:local_auth/local_auth.dart'  import 'package:local_auth_android/local_auth_android.dart'  import 'package:local_auth_darwin/local_auth_darwin.dart'  import '../api/api_client.dart'  import '../providers/auth_provider.dart'    class LoginScreen extends ConsumerStatefulWidget {    const LoginScreen({super.key})      @override    ConsumerState<LoginScreen> createState() => _LoginScreenState()  }    class _LoginScreenState extends ConsumerState<LoginScreen> {    final _emailController = TextEditingController()    final _passwordController = TextEditingController()    final _formKey = GlobalKey<FormState>()    bool _isLoading = false    bool _obscurePassword = true    final LocalAuthentication _localAuth = LocalAuthentication()    bool _biometricAvailable = false    bool _useBiometric = false      @override    void initState() {      super.initState()      _checkBiometric()    }      Future<void> _checkBiometric() async {      final available = await _localAuth.canCheckBiometrics      final enrolled = await _localAuth.isDeviceSupported()      if (mounted) {        setState(() => _biometricAvailable = available && enrolled)      }    }      Future<void> _authenticateWithBiometric() async {      try {        final didAuth = await _localAuth.authenticate(          localizedReason: 'Войдите в Мир Самозанятых',          authMessages: const [            AndroidAuthMessages(              signInTitle: 'Биометрическая авторизация',              cancelButton: 'Отмена',              biometricHint: 'Подтвердите свою личность',            ),            IOSAuthMessages(              cancelButton: 'Отмена',            ),          ],          options: const AuthenticationOptions(            biometricOnly: false,            stickyAuth: true,          ),        )        if (didAuth) {          // Проверяем, есть ли сохраненный токен          final isAuth = await ApiClient().isAuthenticated()          if (isAuth && mounted) {            ref.read(authProvider.notifier).state = true            context.go('/')          } else if (mounted) {            ScaffoldMessenger.of(context).showSnackBar(              const SnackBar(content: Text('Сначала войдите с паролем')),            )          }        }      } catch (e) {        if (mounted) {          ScaffoldMessenger.of(context).showSnackBar(            SnackBar(content: Text('Ошибка биометрии: $e')),          )        }      }    }      Future<void> _login() async {      if (!_formKey.currentState!.validate()) return        setState(() => _isLoading = true)      try {        await ApiClient().login(          _emailController.text.trim(),          _passwordController.text,        )        if (mounted) {          ref.read(authProvider.notifier).state = true          context.go('/')        }      } catch (e) {        if (mounted) {          ScaffoldMessenger.of(context).showSnackBar(            SnackBar(content: Text('Ошибка входа: $e'), backgroundColor: Colors.red),          )        }      } finally {        if (mounted) setState(() => _isLoading = false)      }    }      @override    Widget build(BuildContext context) {      return Scaffold(        body: SafeArea(          child: SingleChildScrollView(            padding: const EdgeInsets.all(24),            child: Form(              key: _formKey,              child: Column(                crossAxisAlignment: CrossAxisAlignment.stretch,                children: [                  const SizedBox(height: 40),                  Container(                    width: 80,                    height: 80,                    decoration: BoxDecoration(                      color: Theme.of(context).colorScheme.primary,                      borderRadius: BorderRadius.circular(20),                    ),                    child: const Icon(Icons.work_outline, size: 40, color: Colors.white),                  ),                  const SizedBox(height: 24),                  const Text('Мир Самозанятых', style: TextStyle(fontSize: 28, fontWeight: FontWeight.bold), textAlign: TextAlign.center),                  const SizedBox(height: 8),                  Text('Вход в личный кабинет', style: TextStyle(fontSize: 16, color: Colors.grey[600]), textAlign: TextAlign.center),                  const SizedBox(height: 40),                  TextFormField(                    controller: _emailController,                    keyboardType: TextInputType.emailAddress,                    decoration: InputDecoration(                      labelText: 'Email',                      prefixIcon: const Icon(Icons.email_outlined),                      border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)),                    ),                    validator: (value) {                      if (value == null || value.isEmpty) return 'Введите email'                      if (!value.contains('@')) return 'Неверный email'                      return null                    },                  ),                  const SizedBox(height: 16),                  TextFormField(                    controller: _passwordController,                    obscureText: _obscurePassword,                    decoration: InputDecoration(                      labelText: 'Пароль',                      prefixIcon: const Icon(Icons.lock_outline),                      suffixIcon: IconButton(                        icon: Icon(_obscurePassword ? Icons.visibility_off : Icons.visibility),                        onPressed: () => setState(() => _obscurePassword = !_obscurePassword),                      ),                      border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)),                    ),                    validator: (value) {                      if (value == null || value.isEmpty) return 'Введите пароль'                      if (value.length < 6) return 'Минимум 6 символов'                      return null                    },                  ),                  const SizedBox(height: 8),                  Align(                    alignment: Alignment.centerRight,                    child: TextButton(onPressed: () {}, child: const Text('Забыли пароль?')),                  ),                  const SizedBox(height: 16),                  ElevatedButton(                    onPressed: _isLoading ? null : _login,                    style: ElevatedButton.styleFrom(padding: const EdgeInsets.symmetric(vertical: 16), shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12))),                    child: _isLoading                      ? const SizedBox(height: 20, width: 20, child: CircularProgressIndicator(strokeWidth: 2))                      : const Text('Войти', style: TextStyle(fontSize: 16)),                  ),                  const SizedBox(height: 16),                  if (_biometricAvailable) ...[                    const Row(children: [Expanded(child: Divider()), Padding(padding: EdgeInsets.symmetric(horizontal: 16), child: Text('или')), Expanded(child: Divider())]),                    const SizedBox(height: 16),                    OutlinedButton.icon(                      onPressed: _authenticateWithBiometric,                      icon: const Icon(Icons.fingerprint),                      label: const Text('Войти по биометрии'),                      style: OutlinedButton.styleFrom(padding: const EdgeInsets.symmetric(vertical: 16), shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12))),                    ),                  ],                  const SizedBox(height: 16),                  Row(mainAxisAlignment: MainAxisAlignment.center, children: [                    Text('Нет аккаунта? ', style: TextStyle(color: Colors.grey[600])),                    TextButton(onPressed: () => context.push('/register'), child: const Text('Зарегистрироваться')),                  ]),                ],              ),            ),          ),        ),      )    }  }